select n.nspname as schema_name,c.relname as table_name,a.attname as column_name,format_type(a.atttypid,a.atttypmod) as data_type from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m') and n.nspname not in ('pg_catalog','information_schema','auth','vault','pg_toast') and (a.attname ~* '(html|gzip)' or (c.relname ~* '(jra|archive|evidence|document)' and a.attname ~* '(body|raw|content)')) order by n.nspname,c.relname,a.attnum limit 100;
